-- State transitions declared for Bucket: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.buckets_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('active', 'archived'), ('active', 'deleted'), ('active', 'readonly'), ('archived', 'active'), ('archived', 'deleted'), ('readonly', 'active'), ('readonly', 'archived'), ('readonly', 'deleted'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: buckets.status % -> %', OLD."status", NEW."status"
            USING ERRCODE = 'check_violation', COLUMN = 'status', CONSTRAINT = 'tg_buckets__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS buckets_status_transition_check ON bucket.buckets;
CREATE TRIGGER buckets_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.buckets
    FOR EACH ROW EXECUTE FUNCTION bucket.buckets_status_transition_check();
